div.script:
(function(){
  var pager = document.getElementById('mv-credit-pager');
  if (!pager) return;
  var slides = Array.prototype.slice.call(pager.querySelectorAll('.mv-credit-slide'));
  var dots   = Array.prototype.slice.call(pager.querySelectorAll('.mv-pager-dot'));
  if (slides.length < 2) return;
  var current = 0;
  function show(idx){
    slides[current].style.display = 'none';
    dots[current].classList.remove('mv-dot-active');
    current = idx;
    slides[current].style.display = '';
    dots[current].classList.add('mv-dot-active');
  }
  pager.addEventListener('click', function(e){
    var btn = e.target.closest ? e.target.closest('.mv-pager-btn') : null;
    if (!btn && e.target.classList.contains('mv-pager-btn')) btn = e.target;
    if (btn){
      e.preventDefault(); e.stopPropagation();
      if (btn.classList.contains('mv-pager-next') && current < slides.length - 1) show(current + 1);
      else if (btn.classList.contains('mv-pager-prev') && current > 0) show(current - 1);
      return;
    }
    window.location.href = '/my/credits';
  });
})();

xpath.script:
(function () {
    window.mvInstallEvent = null;
    window.addEventListener('beforeinstallprompt', function (e) {
        e.preventDefault();
        window.mvInstallEvent = e;
        document.dispatchEvent(new CustomEvent('mv-install-available'));
    });
    window.addEventListener('appinstalled', function () {
        window.mvInstallEvent = null;
        document.dispatchEvent(new CustomEvent('mv-install-done'));
    });
})();
